function catGroups(sys, list) {
  const order = CAT_ORDER[sys] || [];
  const bucket = {};
  for (const c of list) (bucket[c.category] ||= []).push(c);
  const cats = Object.keys(bucket).sort((a, b) => {
    const ia = order.indexOf(a), ib = order.indexOf(b);
    if (ia !== -1 && ib !== -1) return ia - ib;
    if (ia !== -1) return -1;
    if (ib !== -1) return 1;
    return a.localeCompare(b);
  });
  return cats.map((cat) => ({ cat, items: bucket[cat] }));
}
function brandGroups(items) {
  const b = {};
  for (const c of items) (b[c.brand || "Other"] ||= []).push(c);
  return Object.keys(b).sort((a, z) => a.localeCompare(z)).map((brand) => ({ brand, models: b[brand] }));
}
