function partView(p) {
  const e = p.electrical;
  const elec = e ? {
    role: e.role, voltage: e.voltage, contAmps: e.contAmps, maxAmps: e.peakAmps,
    surgeWatts: e.surgeWatts, idleWatts: e.idleWatts, dailyAh: e.dailyAh,
    wireGauge: e.minWireAwg, fuse: e.recommendedFuseA, fuseType: e.fuseType,
    breaker: null, lug: e.terminals, comms: e.comms, switchedBy: e.switchedBy,
    inverterW: e.inverterW, runWatts: e.runWatts,
    confidence: p.confidence, source: (p.sources && p.sources[0]) ? p.sources[0].url : null,
  } : null;
  const cap = p.capacity;
  return {
    id: p.id, name: p.name, brand: p.brand, model: p.model,
    system: p.system, category: p.category, color: SYS_COLOR[p.system] || "blue",
    icon: ICON_BY_CAT[p.category] || Box,
    width: p.dims.w, length: p.dims.l, height: p.dims.h,
    weight: p.weightLb, cost: p.costUsd,
    elec, plumb: p.plumbing, capacity: cap, mounting: p.mounting,
    sources: p.sources || [], confidence: p.confidence, verified: p.verified,
    missing: p.missing || [], needsReview: !!p.needsReview, placeable: !!p.placeable,
    fitType: p.fitType || null, vanFit: p.vanFit || null, position: p.position || null, style: p.style || null,
    wheelWell: (p.tags || []).includes("wheel-well"), tankFit: p.tankFit || null,
    batteryAh: cap && cap.unit === "Ah" && cap.kind === "Battery capacity" ? cap.value : null,
    dailyAh: e ? e.dailyAh : null,
  };
}
