function windowWall(it, van) {
  const pos = (it.c.position || "").toLowerCase();
  if (pos.includes("driver")) return "left";
  if (pos.includes("passenger")) return "right";
  if (pos.includes("rear door")) return "rear";
  if (pos.includes("windshield") || pos.includes("front")) return "front";
  return (it.x ?? 0) < van.intWidth / 2 ? "left" : "right";
}
function wallStart(c, van) {
  const pos = (c.position || "").toLowerCase();
  const x = pos.includes("driver") ? 0 : van.intWidth;
  let y;
  if (pos.includes("forward") || pos.includes("front")) y = Math.min(28, van.intLength * 0.18);
  else if (pos.includes("rear")) y = van.intLength * 0.62;
  else if (pos.includes("sliding")) y = van.intLength * 0.32;
  else y = van.intLength * 0.4;
  return { x, y };
}
