  if (NEEDS_FURRING.includes(choices["Wall Panel"])) furArea += areas.wall;
  if (NEEDS_FURRING.includes(choices["Ceiling Panel"])) furArea += areas.ceiling;
  if (furArea > 0) out.push({ iid: uid(), cid: "mat-furring", qty: Math.max(2, Math.ceil(furArea / 10)), x: 0, y: 0, material: true });
  // L-track (both walls), only if asked
  if (choices.Ltrack === "yes") out.push({ iid: uid(), cid: "mat-ltrack", qty: Math.max(2, Math.ceil((van.intLength * 2) / 48)), x: 0, y: 0, material: true });
