    const len = it.l; const q = it.qty || 1;
    const d = it.c.system === "material" ? (fa + van.intLength / 2) : (fa + (it.y + len / 2));
    const W = (it.weightAdj != null ? it.weightAdj : (it.c.weight || 0)) * q;
