                            <div key={brand}>
                              <div className="px-1 pb-1 text-[10px] font-semibold uppercase tracking-wider text-slate-600">{brand}</div>
                              <div className="space-y-1">{models.map((c) => <PartBtn key={c.id} c={c} />)}</div>
                            </div>
