const _ltOpts = (pred) => PARTS_DB.filter((p) => p.category === "Lighting" && pred(p)).map((p) => ({ value: p.id, label: p.name + (p.costUsd ? " — $" + p.costUsd : "") }));
const LIGHTBAR_OPTIONS = _ltOpts((p) => (p.tags || []).includes("bar"));
