function SizeEditor({ it, onResize }) {
  const f = fp(it.c);
  const w = it.wIn ?? f.w, l = it.lIn ?? f.l, h = it.hIn ?? it.c.height ?? f.h;
  const Row = ({ label, val, dim }) => (
    <div className="flex items-center justify-between rounded-md border border-slate-700 bg-slate-800 px-2 py-1">
      <span className="text-[10px] uppercase tracking-wide text-slate-500">{label}</span>
      <div className="flex items-center gap-1">
        <button onClick={() => onResize(it.iid, dim, -2)} className="flex h-6 w-6 items-center justify-center rounded bg-slate-700 text-base leading-none text-slate-100 active:bg-slate-600">-</button>
        <span className="w-9 text-center text-xs font-semibold text-slate-100">{val}"</span>
        <button onClick={() => onResize(it.iid, dim, 2)} className="flex h-6 w-6 items-center justify-center rounded bg-slate-700 text-base leading-none text-slate-100 active:bg-slate-600">+</button>
      </div>
    </div>
  );
  return (
    <div className="grid grid-cols-2 gap-2">
      <Row label="Width" val={w} dim="w" />
      <Row label="Length" val={l} dim="l" />
      <Row label="Height" val={h} dim="h" />
    </div>
  );
}

