/* ========================================================================== */
function SelectVan({ onPick, onBack }) {
  const [brand, setBrand] = useState(null);
  const brands = useMemo(() => { const seen = []; for (const v of VAN_MODELS) if (!seen.includes(v.make)) seen.push(v.make); return seen; }, []);
  const modelName = (m) => { const v = VAN_MODELS.find((x) => x.make === m); return v ? v.model : m; };
  const groups = useMemo(() => {
    if (!brand) return [];
    const order = [], map = {};
    for (const v of VAN_MODELS) {
      if (v.make !== brand) continue;
      const d = v.model_designation || v.model;
      if (!map[d]) { map[d] = []; order.push(d); }
      map[d].push(v);
    }
    return order.map((d) => ({ desig: d, items: map[d] }));
  }, [brand]);
  return (
    <div className="flex h-[100dvh] w-full flex-col bg-slate-950 font-sans text-slate-200 antialiased">
      <header className="flex shrink-0 items-center gap-3 border-b border-slate-800 bg-slate-900 px-4 py-3">
        <button onClick={() => (brand ? setBrand(null) : onBack())} className="flex h-8 w-8 items-center justify-center rounded-md border border-slate-700 bg-slate-800 text-slate-300 active:bg-slate-700">←</button>
        <div className="text-sm font-semibold text-white">{brand ? `${modelName(brand)} — pick your configuration` : "Choose your van"}</div>
      </header>
      <div className="flex-1 overflow-y-auto p-4">
        <div className="mx-auto max-w-md">
          {!brand ? (
            <div className="grid grid-cols-1 gap-3">
              {brands.map((m) => (
                <button key={m} onClick={() => setBrand(m)} className="flex items-center gap-4 rounded-xl border border-slate-800 bg-slate-900 p-4 text-left active:bg-slate-800">
                  <div className="flex h-14 w-20 shrink-0 items-center justify-center rounded-lg bg-slate-800"><Truck className="h-7 w-7 text-slate-400" /></div>
                  <div className="min-w-0"><div className="text-base font-semibold text-white">{m}</div><div className="text-xs text-slate-500">{modelName(m)} · {VAN_MODELS.filter((v) => v.make === m).length} configurations</div></div>
                  <ChevronDown className="ml-auto h-5 w-5 -rotate-90 text-slate-600" />
                </button>
              ))}
            </div>
          ) : (
            groups.map((g) => (
              <div key={g.desig} className="mb-4">
                <div className="mb-1.5 px-1 text-[11px] font-bold uppercase tracking-widest text-slate-500">{modelName(brand)} {g.desig}</div>
                <div className="grid grid-cols-1 gap-2">
                  {g.items.map((v) => (
                    <button key={v.id} onClick={() => onPick(v.id)} className="flex items-center gap-3 rounded-lg border border-slate-800 bg-slate-900 px-3 py-2.5 text-left active:bg-slate-800">
                      <div className="min-w-0 flex-1"><div className="truncate text-sm font-medium text-white">{trimLabel(v)}</div><div className="text-[11px] text-slate-500">{Math.round(v.interior_L_in)}" cargo · {v.drivetrain}{v.gvwr_lb ? ` · GVWR ${v.gvwr_lb.toLocaleString()} lb` : ""}</div></div>
                      <ChevronDown className="h-4 w-4 -rotate-90 text-slate-600" />
                    </button>
                  ))}
                </div>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
}

/* ========================================================================== */
function TopBar({ stats, van, axle, reviewCount, onHome }) {
  const over = stats.remaining != null && stats.remaining < 0;
  return (
    <header className="flex shrink-0 items-center justify-between border-b border-slate-800 bg-slate-900 px-4 py-2.5">
      <button onClick={onHome} className="flex items-center gap-2.5 text-left">
        <div className="flex h-7 w-7 items-center justify-center rounded-md bg-blue-600"><Truck className="h-4 w-4 text-white" /></div>
        <div className="leading-none"><div className="text-sm font-bold tracking-tight text-white">VanBuilder</div><div className="text-[10px] uppercase tracking-widest text-slate-500">{van.name} · {van.roof_label}</div></div>
      </button>
      <div className="flex items-center gap-3 sm:gap-5">
        {reviewCount > 0 && <span className="flex items-center gap-1 rounded bg-amber-500/15 px-2 py-1 text-[11px] text-amber-300"><AlertTriangle className="h-3 w-3" /> {reviewCount} to verify</span>}
        <HeaderStat label="Weight" value={lb(stats.total)} />
        <HeaderStat label="Cost" value={usd(stats.cost)} />
        {van.payloadKnown ? <HeaderStat label="Payload left" value={lb(stats.remaining)} tone={over ? "red" : stats.remaining < van.payload * 0.15 ? "amber" : "emerald"} />
          : <HeaderStat label="Payload left" value="verify" tone="muted" />}
      </div>
    </header>
  );
}
function HeaderStat({ label, value, tone }) {
  const c = tone === "red" ? "text-red-400" : tone === "amber" ? "text-amber-400" : tone === "emerald" ? "text-emerald-400" : tone === "muted" ? "text-slate-500" : "text-slate-100";
  return <div className="text-right leading-none"><div className="text-[10px] uppercase tracking-wider text-slate-500">{label}</div><div className={`font-mono text-sm font-semibold ${c}`}>{value}</div></div>;
}

function VanLimits({ van, axle }) {
  return (
    <div className="rounded-lg border border-slate-700 bg-slate-800/40 p-2.5">
      <div className="mb-1.5 flex items-center justify-between">
        <span className="flex items-center gap-1.5 text-[10px] font-semibold uppercase tracking-wide text-slate-400"><Ruler className="h-3 w-3" /> Ratings</span>
        {van.complete ? <span className="flex items-center gap-1 text-[10px] text-emerald-400"><BadgeCheck className="h-3 w-3" /> verified</span>
          : <span className="flex items-center gap-1 text-[10px] text-amber-400"><AlertTriangle className="h-3 w-3" /> needs verify</span>}
      </div>
      <LimitRow label="GVWR" v={van.gvwr} est={van.gvwrEstimate} /><LimitRow label="Payload" v={van.payload} />
      <LimitRow label="GAWR front" v={van.gawrF} /><LimitRow label="GAWR rear" v={van.gawrR} />
      <LimitRow label="Curb F / R" v={van.curbF != null && van.curbR != null ? `${van.curbF} / ${van.curbR}` : null} raw />
      <div className="mt-1.5 flex items-center gap-1.5 border-t border-slate-700/60 pt-1.5 text-[10px]">
        <DoorOpen className="h-3 w-3 text-slate-500" />
        <span className="text-slate-500">Side door {van.doors?.side_slider?.height_in ?? "—"}"H · Roof load {van.roofLoadDyn != null ? van.roofLoadDyn + " lb" : "verify"}</span>
      </div>
      <div className="mt-1 text-[10px] text-slate-500">Axle math: {axle.ready ? <span className="text-emerald-400">live</span> : <span className="text-amber-400">pending ({axle.need.join(", ")})</span>}</div>
    </div>
  );
}
function LimitRow({ label, v, raw, est }) {
  const known = v != null;
  let text, cls;
  if (known) { text = (raw ? v : Math.round(v).toLocaleString()) + " lb"; cls = "text-slate-100"; }
  else if (est) {
    const a = Math.round(est.low).toLocaleString(), b = Math.round(est.high).toLocaleString();
    text = est.low === est.high ? `≈${a} lb est.` : `≈${a}–${b} est.`;
    cls = "text-sky-300/90";
  } else { text = "verify"; cls = "text-amber-400/90"; }
  return <div className="flex items-center justify-between py-0.5 font-mono text-[11px]"><span className="text-slate-400">{label}</span><span className={cls}>{text}</span></div>;
}
function Selectish({ value, onChange, options }) {
  return (
    <div className="relative">
      <select value={value} onChange={(e) => onChange(e.target.value)} className="w-full appearance-none rounded-md border border-slate-700 bg-slate-800 px-3 py-2 pr-8 text-sm text-slate-100 outline-none focus:border-blue-500">
        {options.map((o) => <option key={o.value} value={o.value}>{o.label}</option>)}
      </select>
      <ChevronDown className="pointer-events-none absolute right-2 top-2.5 h-4 w-4 text-slate-400" />
    </div>
  );
}

/* ---- floor plan ---------------------------------------------------------- */
function FloorPlan({ van, items, selectedIid, canvasRef, onStartMove, onSelect }) {
  const W = van.intWidth * PX_PER_IN, L = van.intLength * PX_PER_IN, gridStep = 12 * PX_PER_IN;
  return (
    <div className="relative" style={{ width: W + 56, paddingTop: 28, paddingBottom: 28 }}>
      <div className="absolute left-7 right-0 top-0 flex h-7 items-center justify-center rounded-t-lg border border-b-0 border-slate-700 bg-slate-800/60 text-[10px] font-semibold uppercase tracking-widest text-slate-400" style={{ width: W }}>Cab / Front seats</div>
      <div className="absolute left-0 top-1/2 -translate-y-1/2 -rotate-90 text-[10px] font-semibold uppercase tracking-widest text-slate-500">Driver side</div>
      <div className="absolute top-1/2 -translate-y-1/2 rotate-90 text-[10px] font-semibold uppercase tracking-widest text-slate-500" style={{ left: W + 30 }}>Passenger</div>
      <div ref={canvasRef} onPointerDown={() => onSelect(null)} className="relative ml-7 touch-none overflow-hidden border-2 border-slate-600 bg-slate-900" style={{ width: W, height: L }}>
        <svg className="absolute inset-0" width={W} height={L}>
          {Array.from({ length: Math.floor(van.intWidth / 12) }, (_, i) => <line key={"v" + i} x1={(i + 1) * gridStep} y1={0} x2={(i + 1) * gridStep} y2={L} stroke="#1e293b" strokeWidth="1" />)}
          {Array.from({ length: Math.floor(van.intLength / 12) }, (_, i) => <line key={"h" + i} x1={0} y1={(i + 1) * gridStep} x2={W} y2={(i + 1) * gridStep} stroke="#1e293b" strokeWidth="1" />)}
          <line x1={W / 2} y1={0} x2={W / 2} y2={L} stroke="#334155" strokeWidth="1" strokeDasharray="4 4" />
        </svg>
        {(() => {
          const wb = van.wheelbase_in;
          const fo = van.axle && van.axle.front_axle_to_interior_front_in;
          const foUse = (fo != null) ? fo : 50;  // front axle -> interior front (Transit measured; others ~50 assumed)
          const ctr = (wb != null) ? Math.max(24, wb - foUse) : null;  // rear-axle / wheel-well center from interior front
          return van.wells.map((wl, i) => {
            const len = wl.length_in;
            const topIn = (ctr != null) ? (ctr - len / 2) : wl.x_from_front_in;
            return (<React.Fragment key={i}>
              <div className="absolute border border-dashed border-slate-500 bg-slate-700/40" style={{ left: 0, top: topIn * PX_PER_IN, width: wl.intrusion_in * PX_PER_IN, height: len * PX_PER_IN }} title="Wheel well (estimated position)" />
              <div className="absolute border border-dashed border-slate-500 bg-slate-700/40" style={{ right: 0, top: topIn * PX_PER_IN, width: wl.intrusion_in * PX_PER_IN, height: len * PX_PER_IN }} title="Wheel well (estimated position)" />
            </React.Fragment>);
          });
        })()}
        {(() => {
          const sd = van.doors && van.doors.side_slider; if (!sd || !sd.width_in) return null;
          const DOOR_FRONT = { "Mercedes-Benz": 8, "Ford": 16, "Ram": 11 };  // opening front edge from cargo front; Sprinter per layout guides (door starts ~at the bulkhead)
          const dFront = (DOOR_FRONT[van.make] != null) ? DOOR_FRONT[van.make] : 14;
          const dw = sd.width_in;  // opening width runs fore-aft
          const topIn = Math.max(2, Math.min(dFront, van.intLength - dw - 2));
          return (<div className="absolute right-0 z-10 flex flex-col items-center justify-center gap-0.5 border-y-2 border-dashed border-r-4 border-sky-400 bg-sky-400/15" style={{ top: topIn * PX_PER_IN, height: dw * PX_PER_IN, width: 14 }} title={`Side sliding door - ${dw}" opening; front edge ~${dFront}" from cargo front (estimated)`}><DoorOpen className="h-3 w-3 text-sky-300" /><span className="text-[7px] font-bold text-sky-300">~</span></div>);
        })()}
        {items.filter((it) => !it.rack && !it.elec && !it.plumb && !it.shower && it.c.system !== "material" && it.c.category !== "Window" && it.c.category !== "Flare" && it.c.category !== "Lighting" && it.c.category !== "Lighting Bracket" && it.c.category !== "Roof Rack").map((it) => {
          const c = it.c;
          const w = it.w * PX_PER_IN, h = it.l * PX_PER_IN;
          const sel = it.iid === selectedIid; const Icon = c.icon;
          return (
            <div key={it.iid} onPointerDown={(e) => onStartMove(it.iid, e)} title={c.name}
              className={`group touch-none absolute flex cursor-grab flex-col items-center justify-center overflow-hidden rounded-sm border-2 text-center transition-shadow active:cursor-grabbing ${
                it.outside ? "border-red-500 bg-red-500/20" : it.tooTall ? "border-amber-500 bg-amber-500/15" : it.onWell ? "border-orange-400 bg-orange-400/10" : FILL[c.color]
              } ${!c.placeable ? "border-dashed" : ""} ${it.hidden ? "opacity-30" : ""} ${sel ? "z-10 ring-2 ring-blue-400 ring-offset-1 ring-offset-slate-900" : "z-0"}`}
              style={{ left: it.x * PX_PER_IN, top: it.y * PX_PER_IN, width: it.hidden ? 20 : Math.max(w, 28), height: it.hidden ? 20 : Math.max(h, 28), touchAction: "none" }}>
              <Icon className="h-3.5 w-3.5 text-slate-200" />
              {!it.hidden && h > 34 && <span className="mt-0.5 px-1 text-[9px] font-medium leading-tight text-slate-200">{c.name}</span>}
              {it.outside && <AlertTriangle className="absolute right-0.5 top-0.5 h-3 w-3 text-red-400" />}
              {!it.outside && it.tooTall && <ArrowUp className="absolute right-0.5 top-0.5 h-3 w-3 text-amber-400" />}
              {c.needsReview && !it.outside && !it.tooTall && <span className="absolute right-0.5 top-0.5 h-1.5 w-1.5 rounded-full bg-amber-400" />}
            </div>
          );
        })}
        {items.length === 0 && <div className="pointer-events-none absolute inset-0 flex items-center justify-center px-8 text-center text-xs text-slate-600">Tap or drag a part to add it. Canvas is sized to this trim ({van.intLength}" × {van.intWidth}").</div>}
      </div>
      <div className="pointer-events-none absolute z-40" style={{ left: 28, top: 28, width: W, height: L }}>
        {(() => {
          const well = (van.wells && van.wells.length) ? van.wells.reduce((a, b) => (b.x_from_front_in > a.x_from_front_in ? b : a)) : null;
          const wc = well ? well.x_from_front_in + (well.length_in || 28) / 2
                   : (van.wheelbase_in != null ? Math.max(24, van.wheelbase_in - ((van.axle && van.axle.front_axle_to_interior_front_in) || 48)) : van.intLength * 0.6);
          const extended = (van.intLength - wc) > 35;
          const cl = (v, max) => Math.max(0, Math.min(v, max)) * PX_PER_IN;
          return items.filter((it) => it.c.category === "Window" || it.c.category === "Flare").map((it) => {
            const c = it.c; const sel = it.iid === selectedIid; const T = 22;
            if (c.category === "Flare") {
              const FL = Math.min(it.l, van.intLength);
              const along = FL * PX_PER_IN;
              const top = cl(extended ? wc - FL * 0.12 : wc - FL / 2, van.intLength - FL);
              return (
                <React.Fragment key={it.iid}>
                  {["L", "R"].map((sd) => (
                    <div key={sd} onPointerDown={(e) => { e.stopPropagation(); onSelect(it.iid); }} title={`${c.name} — fixed at the wheel wells (driver + passenger)`}
                      className={`pointer-events-auto absolute flex items-center justify-center rounded-sm border-2 bg-emerald-500/70 ${sel ? "border-blue-200 ring-2 ring-blue-400" : "border-emerald-200"}`}
                      style={{ left: sd === "L" ? -T : W, top, width: T, height: along }}>
                      <Layers className="h-3.5 w-3.5 text-emerald-50" />
                    </div>
                  ))}
                </React.Fragment>
              );
            }
            const wall = windowWall(it, van); const side = wall === "left" || wall === "right";
            const along = Math.max(it.l * PX_PER_IN, 38);
            let style;
            if (wall === "left") style = { left: -T, top: cl(it.y, van.intLength - it.l), width: T, height: along };
            else if (wall === "right") style = { left: W, top: cl(it.y, van.intLength - it.l), width: T, height: along };
            else if (wall === "front") style = { top: -T, left: cl(it.x, van.intWidth - it.l), width: along, height: T };
            else style = { top: L, left: cl(it.x, van.intWidth - it.l), width: along, height: T };
            return (
              <div key={it.iid} onPointerDown={(e) => onStartMove(it.iid, e)} title={`${c.name} (drag along ${wall === "left" ? "driver" : wall === "right" ? "passenger" : wall} wall)`}
                className={`pointer-events-auto touch-none absolute flex cursor-grab items-center justify-center rounded-sm border-2 bg-sky-500/70 active:cursor-grabbing ${sel ? "border-blue-200 ring-2 ring-blue-400" : "border-sky-100"}`}
                style={{ ...style, touchAction: "none" }}>
                <DoorOpen className={`h-3.5 w-3.5 text-sky-50 ${side ? "" : "rotate-90"}`} />
              </div>
            );
          });
        })()}
      </div>
      <div className="ml-7 mt-1 flex items-center justify-center gap-1 text-[10px] font-semibold uppercase tracking-widest text-slate-500" style={{ width: W }}><span className="h-px flex-1 bg-slate-700" /> Rear doors <span className="h-px flex-1 bg-slate-700" /></div>
      <div className="ml-7 mt-1 text-center font-mono text-[10px] text-slate-600" style={{ width: W }}>{van.name} · {van.roof_label} {van.roofH}" · {van.intLength}"×{van.intWidth}" · grid 1 ft</div>
    </div>
  );
}

/* ---- properties (database record) --------------------------------------- */
function Properties({ it, van, onRemove, onRotate, onDup, onHide, onResize }) {
  const c = it.c, Icon = c.icon, ew = elecWarnings(c);
  return (
    <div className="rounded-lg border border-slate-700 bg-slate-800/50 p-3">
      <div className="flex items-center gap-2">
        <span className={`flex h-7 w-7 items-center justify-center rounded ${DOT[c.color]} bg-opacity-20`}><Icon className="h-4 w-4 text-slate-100" /></span>
        <div className="min-w-0 flex-1"><div className="truncate text-sm font-semibold text-white">{c.name}</div><div className="truncate text-[11px] text-slate-400">{c.category} · {c.brand} {c.model}</div></div>
        <ConfBadge level={c.confidence} />
      </div>

      {it.outside && <Flag tone="red" icon={AlertTriangle} text="Outside van boundary" />}
      {!it.outside && it.tooTall && <Flag tone="amber" icon={ArrowUp} text={`Taller than roof (${c.height}" > ${van.roofH}")`} />}
      {!it.outside && it.onWell && <Flag tone="orange" icon={AlertTriangle} text="Sits over a wheel well" />}
      {!c.placeable && <Flag tone="amber" icon={AlertTriangle} text="No dimensions in DB — default footprint shown" />}
      {c.missing.length > 0 && <Flag tone="amber" icon={AlertTriangle} text={`Missing in DB: ${c.missing.map((m) => FIELD_LABEL[m] || m).join(", ")}`} />}
      {!c.verified && c.missing.length === 0 && <Flag tone="amber" icon={Info} text="Not human-verified yet" />}

      <div className="mt-3 grid grid-cols-2 gap-2 font-mono text-xs">
        <Spec k="Width" v={c.width != null ? `${c.width}"` : "—"} danger={c.width == null} />
        <Spec k="Length" v={c.length != null ? `${c.length}"` : "—"} danger={c.length == null} />
        <Spec k="Height" v={c.height != null ? `${c.height}"` : "—"} danger={c.height == null || it.tooTall} />
        <Spec k="Weight" v={lb(c.weight)} danger={c.weight == null} />
        <Spec k="Cost" v={usd(c.cost)} danger={c.cost == null} />
        {c.capacity?.value != null && <Spec k={c.capacity.kind} v={`${c.capacity.value} ${c.capacity.unit}`} />}
        {c.dailyAh && <Spec k="Draw" v={`~${c.dailyAh} Ah/day`} />}
      </div>

      {c.mounting?.notes && <p className="mt-3 rounded border border-slate-700 bg-slate-900/60 p-2 text-[11px] leading-relaxed text-slate-400"><span className="font-semibold text-slate-300">Mounting: </span>{c.mounting.notes}</p>}
      {c.elec && <ElecSpecCard e={c.elec} warns={ew} />}
      {c.plumb && <PlumbSpecCard p={c.plumb} />}
      {c.sources.length > 0 && <a href={c.sources[0].url} target="_blank" rel="noopener" className="mt-2 block truncate text-[11px] text-sky-400">Source: {c.sources[0].label}</a>}

      <div className="mt-3 text-[10px] uppercase tracking-widest text-slate-500">Size — adjust to fit</div>
      <div className="mt-1.5"><SizeEditor it={it} onResize={onResize} /></div>
      <div className="mt-3 grid grid-cols-2 gap-2">
        <ActBtn icon={RotateCw} label="Rotate" onClick={() => onRotate(it.iid)} />
        <ActBtn icon={it.hidden ? Eye : EyeOff} label={it.hidden ? "Show" : "Hide"} onClick={() => onHide(it.iid)} />
        <ActBtn icon={Copy} label="Copy" onClick={() => onDup(it.iid)} />
        <ActBtn icon={Trash2} label="Delete" danger onClick={() => onRemove(it.iid)} />
      </div>
    </div>
  );
}
function Flag({ tone, icon: Icon, text }) {
  const c = tone === "red" ? "border-red-500/50 bg-red-500/10 text-red-300" : tone === "orange" ? "border-orange-400/50 bg-orange-400/10 text-orange-300" : "border-amber-500/50 bg-amber-500/10 text-amber-300";
  return <div className={`mt-2 flex items-center gap-1.5 rounded border px-2 py-1 text-[11px] ${c}`}><Icon className="h-3.5 w-3.5 shrink-0" /> {text}</div>;
}
function ElecSpecCard({ e, warns }) {
  return (
    <div className="mt-3 rounded-lg border border-amber-500/25 bg-amber-500/5 p-2.5">
      <div className="mb-2 flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-amber-300"><Zap className="h-3.5 w-3.5" /> Electrical (from DB)</div>
      <div className="grid grid-cols-2 gap-1.5 font-mono text-[11px]">
        <Spec k="Voltage" v={e.voltage} /><Spec k="Cont. amps" v={e.contAmps != null ? `${e.contAmps} A` : "—"} />
        <Spec k="Peak" v={e.maxAmps != null ? `${e.maxAmps} A` : "—"} /><Spec k="Surge" v={e.surgeWatts != null ? `${e.surgeWatts} W` : "—"} />
        <Spec k="Wire" v={e.wireGauge || "—"} danger={!e.wireGauge && e.role !== "source"} />
        <Spec k="Fuse" v={e.fuse != null ? `${e.fuse} A ${e.fuseType || ""}` : "—"} danger={e.fuse == null && e.role === "load" && !isAC(e.voltage)} />
        <Spec k="Switched by" v={e.switchedBy || "—"} /><Spec k="Comms" v={e.comms || "—"} />
        <Spec k="Terminals" v={e.lug || "—"} /><Spec k="Source" v={e.source ? "on file" : "—"} danger={!e.source} />
      </div>
      {warns.length > 0 && <div className="mt-2 space-y-1 border-t border-amber-500/20 pt-2">{warns.map((w, i) => <WarnLine key={i} w={w} />)}</div>}
    </div>
  );
}
function PlumbSpecCard({ p }) {
  return (
    <div className="mt-3 rounded-lg border border-cyan-500/25 bg-cyan-500/5 p-2.5">
      <div className="mb-2 flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-cyan-300"><Droplets className="h-3.5 w-3.5" /> Plumbing (from DB)</div>
      <div className="grid grid-cols-2 gap-1.5 font-mono text-[11px]">
        <Spec k="Fluid" v={titleCase(p.fluid)} danger={!p.fluid} />
        {p.tankGal != null && <Spec k="Tank" v={`${p.tankGal} gal`} />}
        {p.flowGpm != null && <Spec k="Flow" v={`${p.flowGpm} gpm`} />}
        {p.connectionSizeIn != null && <Spec k="Conn." v={`${p.connectionSizeIn}"`} />}
        <Spec k="Powered" v={p.powered ? "yes" : "no"} />{p.valveType && <Spec k="Valve" v={titleCase(p.valveType)} />}
      </div>
    </div>
  );
}
function Spec({ k, v, danger }) { return <div className="rounded bg-slate-900/60 px-2 py-1"><div className="text-[9px] uppercase tracking-wide text-slate-500">{k}</div><div className={danger ? "text-amber-400" : "text-slate-100"}>{v}</div></div>; }
function ConfBadge({ level }) { const m = CONF[level] || CONF.unverified; return <span className={`shrink-0 rounded border px-1.5 py-0.5 text-[10px] font-medium ${m.badge}`}>{m.label}</span>; }
function WarnLine({ w }) { const tone = w.level === "error" ? "text-red-300" : w.level === "warn" ? "text-amber-300" : "text-sky-300"; const Icon = w.level === "info" ? Info : AlertTriangle; return <div className={`flex items-start gap-1.5 text-[11px] ${tone}`}><Icon className="mt-0.5 h-3 w-3 shrink-0" /> {w.msg}</div>; }
function ActBtn({ icon: Icon, label, onClick, danger }) { return <button onClick={onClick} className={`flex flex-col items-center gap-1 rounded-md border px-2 py-1.5 text-[10px] transition ${danger ? "border-red-900 bg-red-950/40 text-red-300 hover:bg-red-900/40" : "border-slate-700 bg-slate-800 text-slate-300 hover:bg-slate-700"}`}><Icon className="h-3.5 w-3.5" /> {label}</button>; }

/* ---- build stats (right) ------------------------------------------------- */
function BuildStats({ stats, van, axle, count }) {
  const over = stats.remaining != null && stats.remaining < 0;
  const pct = van.payloadKnown ? Math.min(100, Math.max(0, (stats.total / van.payload) * 100)) : 0;
  return (
    <div className="space-y-3">
      {van.payloadKnown ? (
        <div>
          <div className="mb-1 flex items-center justify-between text-[11px]"><span className="text-slate-400">Payload used</span><span className={`font-mono font-semibold ${over ? "text-red-400" : "text-slate-200"}`}>{lb(stats.total)} / {lb(van.payload)}</span></div>
          <div className="h-2.5 w-full overflow-hidden rounded-full bg-slate-800"><div className={`h-full rounded-full ${over ? "bg-red-500" : pct > 85 ? "bg-amber-500" : "bg-blue-500"}`} style={{ width: `${pct}%` }} /></div>
          <div className="mt-1 text-right font-mono text-[10px] text-slate-500">{over ? `${lb(-stats.remaining)} OVER limit` : `${lb(stats.remaining)} remaining`}</div>
        </div>
      ) : (
        <div className="rounded-lg border border-amber-500/30 bg-amber-500/5 p-2.5"><div className="flex items-center gap-1.5 text-[11px] font-semibold text-amber-300"><AlertTriangle className="h-3.5 w-3.5" /> Payload not verified</div><p className="mt-1 text-[11px] leading-snug text-slate-400">No confirmed GVWR/curb for this trim yet. Build weight tracked below.</p></div>
      )}
      <StatRow label="Components" value={count} mono />
      <StatRow label="Dry build weight" value={lb(stats.dry)} mono />
      {stats.unknownWt > 0 && <div className="flex items-center gap-1.5 text-[10px] text-amber-400"><AlertTriangle className="h-3 w-3" /> {stats.unknownWt} part(s) missing weight in DB</div>}
      <StatRow label="Water (fresh, full)" value={lb(stats.fluids)} mono />
      <StatRow label="Total weight" value={lb(stats.total)} mono strong />
      <StatRow label="Total cost" value={usd(stats.cost)} mono strong />
      <AxleCard axle={axle} />
    </div>
  );
}
function AxleCard({ axle }) {
  if (!axle.ready) return (
    <div className="rounded-lg border border-slate-700 bg-slate-800/40 p-3">
      <div className="mb-1 flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-slate-400"><Scale className="h-3.5 w-3.5" /> Axle loads</div>
      <p className="text-[11px] text-slate-500">Live axle analysis pending — needs {axle.need.join(", ")} for this trim (in the sourcing queue).</p>
    </div>
  );
  return (
    <div className="rounded-lg border border-slate-700 bg-slate-800/40 p-3">
      <div className="mb-2 flex items-center justify-between"><span className="flex items-center gap-1.5 text-[11px] font-semibold uppercase tracking-wide text-slate-400"><Scale className="h-3.5 w-3.5" /> Axle loads (live)</span>{axle.estimate && <span className="text-[9px] uppercase tracking-wide text-amber-400">ref. estimate</span>}</div>
      <AxleRow label="Front axle" load={axle.front} gawr={axle.gawrF} over={axle.overF} />
      <AxleRow label="Rear axle" load={axle.rear} gawr={axle.gawrR} over={axle.overR} />
      <AxleRow label="GVW" load={axle.gvw} gawr={axle.gvwr} over={axle.overG} />
      <p className="mt-2 text-[10px] leading-snug text-slate-500">Curb + build reactions (W×d/wheelbase). Build adds {lb(axle.buildFront)} front / {lb(axle.buildRear)} rear.</p>
    </div>
  );
}
function AxleRow({ label, load, gawr, over }) {
  const pct = gawr ? Math.min(100, (load / gawr) * 100) : 0;
  return (
    <div className="mb-1.5">
      <div className="flex justify-between font-mono text-[11px]"><span className="text-slate-300">{label}</span><span className={over ? "text-red-400" : "text-slate-300"}>{lb(load)} / {lb(gawr)}</span></div>
      <div className="mt-0.5 h-1.5 w-full overflow-hidden rounded-full bg-slate-700"><div className={`h-full rounded-full ${over ? "bg-red-500" : pct > 90 ? "bg-amber-500" : "bg-emerald-500"}`} style={{ width: `${pct}%` }} /></div>
    </div>
  );
}
function StatRow({ label, value, mono, strong }) { return <div className="flex items-center justify-between"><span className="text-[12px] text-slate-400">{label}</span><span className={`${mono ? "font-mono" : ""} text-sm ${strong ? "font-bold text-white" : "text-slate-200"}`}>{value}</span></div>; }
function Balance({ left, right, l, r }) { const tot = l + r || 1, lp = (l / tot) * 100; return <div><div className="mb-1 flex justify-between font-mono text-[11px] text-slate-300"><span>{left} {lb(l)}</span><span>{right} {lb(r)}</span></div><div className="flex h-2 w-full overflow-hidden rounded-full bg-slate-700"><div className="h-full bg-blue-500" style={{ width: `${lp}%` }} /><div className="h-full bg-sky-400" style={{ width: `${100 - lp}%` }} /></div></div>; }

/* ---- bottom tabs --------------------------------------------------------- */
const TABS = [{ id: "Materials", icon: Package }, { id: "Electrical", icon: Zap }, { id: "Plumbing", icon: Droplets }, { id: "Weight", icon: Scale }];
function BottomPanel({ tab, setTab, items, stats, van, elec, axle, roof, anyOutside, anyTall, elecFlags, axleFlag, reviewCount }) {
  return (
    <div className="flex h-72 shrink-0 flex-col border-t border-slate-800 bg-slate-900">
      <div className="flex shrink-0 items-center gap-1 border-b border-slate-800 px-2">
        {TABS.map((t) => {
          const Icon = t.icon, active = tab === t.id;
          const flag = (t.id === "Electrical" && elecFlags) || (t.id === "Weight" && (anyTall || axleFlag)) || (t.id === "Materials" && reviewCount > 0);
          return <button key={t.id} onClick={() => setTab(t.id)} className={`flex items-center gap-1.5 border-b-2 px-3 py-2 text-xs font-medium transition ${active ? "border-blue-500 text-blue-400" : "border-transparent text-slate-400 hover:text-slate-200"}`}><Icon className="h-3.5 w-3.5" /> {t.id}{flag && <span className="h-1.5 w-1.5 rounded-full bg-amber-400" />}</button>;
        })}
        {anyOutside && <span className="ml-auto flex items-center gap-1 rounded bg-red-500/15 px-2 py-1 text-[11px] text-red-400"><AlertTriangle className="h-3 w-3" /> Items outside boundary</span>}
      </div>
      <div className="min-h-0 flex-1 overflow-y-auto p-4">
        {tab === "Materials" && <MaterialsTab items={items} stats={stats} />}
        {tab === "Electrical" && <ElectricalTab elec={elec} />}
        {tab === "Plumbing" && <PlumbingTab items={items} stats={stats} />}
        {tab === "Weight" && <WeightTab items={items} stats={stats} van={van} axle={axle} roof={roof} />}
      </div>
    </div>
  );
}
function Empty({ text }) { return <div className="py-8 text-center text-sm text-slate-500">{text}</div>; }

function MaterialsTab({ items, stats }) {
  if (!items.length) return <Empty text="Add components to generate the BOM from the database." />;
  const groups = {};
  for (const it of items) (groups[it.c.system] ||= []).push(it);
  return (
    <div className="space-y-4">
      {Object.entries(groups).map(([sys, list]) => {
        const agg = {};
        for (const it of list) { const id = it.c.id; (agg[id] ||= { c: it.c, qty: 0, wt: it.weightAdj != null ? it.weightAdj : it.c.weight, cost: it.costAdj != null ? it.costAdj : it.c.cost }); agg[id].qty += (it.qty || 1); }
        const rows = Object.values(agg);
        return (
          <div key={sys}>
            <div className="mb-1.5 flex items-center gap-1.5"><span className={`h-2 w-2 rounded-full ${DOT[SYS_COLOR[sys]]}`} /><span className="text-[11px] font-semibold uppercase tracking-wide text-slate-300">{SYS_LABEL[sys]}</span></div>
            <table className="w-full text-left text-xs">
              <thead className="text-[10px] uppercase tracking-wide text-slate-500"><tr><th className="py-1 font-medium">Part</th><th className="font-medium">Brand / model</th><th className="font-medium">Qty</th><th className="font-medium">Unit wt</th><th className="font-medium">Cost</th><th className="font-medium">Status</th></tr></thead>
              <tbody>{rows.map((r) => (
                <tr key={r.c.id} className="border-t border-slate-800">
                  <td className="py-1.5 pr-2 text-slate-200">{r.c.name}</td>
                  <td className="pr-2 font-mono text-[11px] text-slate-400">{r.c.brand} {r.c.model}</td>
                  <td className="font-mono text-slate-300">×{r.qty}</td>
                  <td className="font-mono text-slate-400">{r.wt != null ? Math.round(r.wt) + " lb" : "—"}</td>
                  <td className="font-mono text-slate-400">{r.cost != null ? usd(r.cost * r.qty) : "—"}</td>
                  <td>{r.c.needsReview ? <span className="text-[10px] text-amber-400">verify</span> : <span className="text-[10px] text-emerald-400">ok</span>}</td>
                </tr>
              ))}</tbody>
            </table>
          </div>
        );
      })}
      <div className="flex justify-end gap-6 border-t border-slate-700 pt-2 font-mono text-xs text-slate-300"><span>Items: {items.length}</span><span>Dry weight: {lb(stats.dry)}</span><span className="font-semibold text-white">Cost: {usd(stats.cost)}</span></div>
    </div>
  );
}

function ElectricalTab({ elec }) {
  const { circuits, batteryAh, batteryWh, dailyAh, days, invWatts, dcLoadAmps, acLoadWatts, sys } = elec;
  const allWarns = [...sys, ...circuits.flatMap((it) => elecWarnings(it.c).map((w) => ({ ...w, who: it.c.name })))];
  const rank = { error: 0, warn: 1, info: 2 };
  return (
    <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
      <div>
        <Heading text="Circuits (from DB)" />
        <div className="mb-3 grid grid-cols-3 gap-2"><Stat big label="Battery" value={`${batteryAh} Ah`} /><Stat big label="Energy" value={`${batteryWh} Wh`} /><Stat big label="Autonomy" value={days ? `${days.toFixed(1)} d` : "—"} /></div>
        {circuits.length === 0 ? <Empty text="Add an electrical part — it appears here from the database." /> : (
          <table className="w-full text-left text-xs">
            <thead className="text-[10px] uppercase tracking-wide text-slate-500"><tr><th className="py-1 font-medium">Circuit</th><th className="font-medium">V</th><th className="font-medium">Cont A</th><th className="font-medium">Wire</th><th className="font-medium">Protect</th><th className="font-medium"></th></tr></thead>
            <tbody>{circuits.map((it) => {
              const e = it.c.elec, lvl = worst(elecWarnings(it.c));
              const protect = e.fuse != null ? `${e.fuse}A ${e.fuseType || ""}` : isAC(e.voltage) ? "AC breaker" : "—";
              return (<tr key={it.iid} className="border-t border-slate-800">
                <td className="py-1.5 pr-2 text-slate-200">{it.c.name}</td><td className="font-mono text-slate-400">{e.voltage}</td>
                <td className="font-mono text-slate-400">{e.contAmps != null ? e.contAmps : "—"}</td>
                <td className={`font-mono ${e.wireGauge || e.role === "source" ? "text-slate-400" : "text-amber-400"}`}>{e.wireGauge || "—"}</td>
                <td className={`font-mono ${e.fuse == null && e.role === "load" && !isAC(e.voltage) ? "text-amber-400" : "text-slate-400"}`}>{protect}</td>
                <td>{lvl === "ok" ? <CheckCircle2 className="h-3.5 w-3.5 text-emerald-400" /> : <AlertTriangle className={`h-3.5 w-3.5 ${lvl === "error" ? "text-red-400" : lvl === "warn" ? "text-amber-400" : "text-sky-400"}`} />}</td>
              </tr>);
            })}</tbody>
          </table>
        )}
        {(dcLoadAmps > 0 || acLoadWatts > 0) && <p className="mt-2 font-mono text-[11px] text-slate-500">DC {dcLoadAmps}A · AC {acLoadWatts}W · inverter {invWatts}W · daily {dailyAh} Ah</p>}
      </div>
      <div>
        <Heading text="Wiring checks" />
        {allWarns.length === 0 ? (circuits.length ? <div className="flex items-center gap-2 rounded-md border border-emerald-500/40 bg-emerald-500/10 px-3 py-2 text-xs text-emerald-300"><CheckCircle2 className="h-4 w-4" /> Every circuit has a gauge and protection.</div> : <Empty text="Checks run as you add electrical parts." />) : (
          <div className="space-y-1.5">{allWarns.slice().sort((a, b) => rank[a.level] - rank[b.level]).map((w, i) => (
            <div key={i} className={`flex items-start gap-2 rounded-md border px-3 py-2 text-xs ${w.level === "error" ? "border-red-500/40 bg-red-500/10 text-red-300" : w.level === "warn" ? "border-amber-500/40 bg-amber-500/10 text-amber-300" : "border-sky-500/40 bg-sky-500/10 text-sky-300"}`}>{w.level === "info" ? <Info className="mt-0.5 h-3.5 w-3.5 shrink-0" /> : <AlertTriangle className="mt-0.5 h-3.5 w-3.5 shrink-0" />}<span>{w.who && <span className="font-medium">{w.who}: </span>}{w.msg}</span></div>
          ))}</div>
        )}
        <p className="mt-3 flex items-start gap-1.5 text-[11px] text-slate-500"><Cable className="mt-0.5 h-3.5 w-3.5 shrink-0" /> Specs come from the parts database. Size to your real loads and run length before wiring.</p>
      </div>
    </div>
  );
}

function PlumbingTab({ items, stats }) {
  const plumb = items.filter((it) => it.c.plumb);
  return (
    <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
      <div>
        <Heading text="Water system (from DB)" />
        <div className="grid grid-cols-2 gap-2"><Stat big label="Fresh" value={`${stats.freshGal} gal`} /><Stat big label="Gray" value={`${stats.grayGal} gal`} /></div>
        <p className="mt-2 font-mono text-[11px] text-slate-500">Fresh water adds {lb(stats.fluids)} full ({WATER_LB_PER_GAL} lb/gal).</p>
      </div>
      <div>
        <Heading text="Fixtures & tanks" />
        <div className="space-y-1">{plumb.length ? plumb.map((it) => {
          const p = it.c.plumb;
          const right = p.tankGal ? `${p.tankGal} gal` : p.flowGpm ? `${p.flowGpm} gpm` : usd(it.c.cost);
          return <Row key={it.iid} name={it.c.name} right={`${titleCase(p.fluid)} · ${right}${p.powered ? " · powered" : ""}`} color="cyan" />;
        }) : <Empty text="No plumbing parts placed." />}</div>
        <p className="mt-2 text-[11px] text-slate-500">Powered devices (pump, valves) are bought here; their wiring lives in the electrical BOM — never double-counted.</p>
      </div>
    </div>
  );
}

function smartWarnings(items, van) {
  const out = [];
  const some = (f) => items.some(f);
  const cat = (c) => items.some((it) => it.c.category === c);
  const isBattery = (it) => (it.c.batteryAh && it.c.batteryAh > 0) || (it.c.capacity && it.c.capacity.kind === "Battery capacity");
  const isInverter = (it) => it.c.elec && it.c.elec.inverterW && it.c.elec.inverterW > 0;
  const acLoad = (it) => it.c.elec && it.c.elec.role === "load" && (it.c.elec.voltage === "120V" || (it.c.elec.runWatts && it.c.elec.runWatts > 0));
  const dcLoad = (it) => it.c.elec && it.c.elec.role === "load";
  const freshDraw = (it) => it.c.plumb && it.c.plumb.fluid === "fresh" && it.c.category !== "Fresh Tank";
  const drains = (it) => it.c.category === "Sink" || it.c.category === "Shower";
  if (some(acLoad) && !some(isInverter) && !cat("AC Inlet")) out.push({ tone: "amber", text: "120V appliance with no inverter or shore inlet to power it" });
  if (some(dcLoad) && !some(isBattery)) out.push({ tone: "amber", text: "12V loads but no house battery in the build" });
  if (some(isInverter) && !some(isBattery)) out.push({ tone: "amber", text: "Inverter with no battery bank to draw from" });
  if (cat("Solar Panel") && !cat("Charge Controller")) out.push({ tone: "amber", text: "Solar panel needs an MPPT charge controller" });
  if (some(freshDraw) && !cat("Fresh Tank")) out.push({ tone: "amber", text: "Water fixtures but no fresh water tank" });
  if (some(drains) && !cat("Gray Tank")) out.push({ tone: "amber", text: "Sink/shower should drain to a gray tank" });
  if ((cat("Shower") || cat("Sink") || cat("Water Heater")) && !cat("Water Pump")) out.push({ tone: "amber", text: "Pressurized water needs a 12V water pump" });
  if (cat("Water Heater") && !cat("Fresh Tank")) out.push({ tone: "amber", text: "Water heater with no fresh water source" });
  return out;
}
function WeightTab({ items, stats, van, axle, roof }) {
  const bySys = {}; for (const it of items) bySys[it.c.system] = (bySys[it.c.system] || 0) + (it.c.weight || 0);
  const cats = Object.entries(bySys).sort((a, b) => b[1] - a[1]); const maxCat = Math.max(1, ...cats.map(([, v]) => v));
  const tall = items.filter((it) => it.tooTall);
  const badges = [];
  if (axle.ready) {
    if (axle.overF) badges.push({ tone: "red", text: `Front axle over GAWR by ${lb(axle.front - axle.gawrF)}` });
    if (axle.overR) badges.push({ tone: "red", text: `Rear axle over GAWR by ${lb(axle.rear - axle.gawrR)}` });
    if (axle.overG) badges.push({ tone: "red", text: `Over GVWR by ${lb(axle.gvw - axle.gvwr)}` });
    if (!axle.overF && !axle.overR && !axle.overG) badges.push({ tone: "emerald", text: "Within all axle & GVWR limits" });
  } else badges.push({ tone: "amber", text: `Axle analysis pending — needs ${axle.need.join(", ")}` });
  if (roof.over) badges.push({ tone: "amber", text: `Roof load ${lb(roof.w)} over rating ${lb(roof.rating)}` });
  for (const it of tall) badges.push({ tone: "amber", text: `${it.c.name} taller than roof (${it.c.height}" > ${van.roofH}")` });
  if (stats.unknownWt > 0) badges.push({ tone: "amber", text: `${stats.unknownWt} part(s) missing weight in DB` });
  for (const b of smartWarnings(items, van)) badges.push(b);

  return (
    <div className="grid grid-cols-1 gap-4 lg:grid-cols-2">
      <div>
        <Heading text="Weight by system (dry)" />
        {cats.length ? (
          <div className="space-y-2">
            {cats.map(([sys, w]) => (
              <div key={sys}><div className="mb-0.5 flex justify-between text-[11px]"><span className="text-slate-300">{SYS_LABEL[sys]}</span><span className="font-mono text-slate-400">{lb(w)}</span></div><div className="h-2 w-full overflow-hidden rounded-full bg-slate-800"><div className={`h-full rounded-full ${DOT[SYS_COLOR[sys]]}`} style={{ width: `${(w / maxCat) * 100}%` }} /></div></div>
            ))}
            <div className="flex justify-between border-t border-slate-700 pt-2 font-mono text-xs"><span className="text-slate-400">Dry total</span><span className="text-slate-200">{lb(stats.dry)}</span></div>
            <div className="flex justify-between font-mono text-xs"><span className="text-slate-400">+ Fresh water</span><span className="text-slate-200">{lb(stats.fluids)}</span></div>
            <div className="flex justify-between font-mono text-xs font-semibold"><span className="text-white">Total</span><span className="text-white">{lb(stats.total)}</span></div>
          </div>
        ) : <Empty text="Add components to see the weight breakdown." />}
      </div>
      <div>
        <Heading text={`Engineering warnings · ${van.name}`} />
        <div className="space-y-2">{badges.map((b, i) => (
          <div key={i} className={`flex items-center gap-2 rounded-md border px-3 py-2 text-xs ${b.tone === "red" ? "border-red-500/50 bg-red-500/10 text-red-300" : b.tone === "amber" ? "border-amber-500/50 bg-amber-500/10 text-amber-300" : "border-emerald-500/50 bg-emerald-500/10 text-emerald-300"}`}>{b.tone === "emerald" ? <Gauge className="h-4 w-4" /> : <AlertTriangle className="h-4 w-4" />} {b.text}</div>
        ))}{!items.length && <Empty text="No build yet." />}</div>
        {axle.ready ? (
          <div className="mt-3 rounded-lg border border-slate-700 bg-slate-800/40 p-3">
            <div className="mb-1 text-[11px] font-semibold uppercase tracking-wide text-slate-400">Live axle reactions{axle.estimate ? " (ref. estimate)" : ""}</div>
            <AxleRow label="Front" load={axle.front} gawr={axle.gawrF} over={axle.overF} />
            <AxleRow label="Rear" load={axle.rear} gawr={axle.gawrR} over={axle.overR} />
            <AxleRow label="GVW" load={axle.gvw} gawr={axle.gvwr} over={axle.overG} />
          </div>
        ) : (
          <div className="mt-3 grid grid-cols-2 gap-2"><Stat label="GVWR" value={van.gvwr != null ? lb(van.gvwr) : "verify"} /><Stat label="Payload" value={van.payloadKnown ? lb(van.payload) : "verify"} /><Stat label="GAWR front" value={van.gawrF != null ? lb(van.gawrF) : "verify"} /><Stat label="GAWR rear" value={van.gawrR != null ? lb(van.gawrR) : "verify"} /></div>
        )}
        <p className="mt-2 text-[11px] text-slate-500">Limits come from the van engineering database. Axle reactions use curb + W×d/wheelbase per Spec §4.8.</p>
      </div>
    </div>
  );
}

/* ---- shared ---- */
function Heading({ text }) { return <div className="mb-2 text-[11px] font-semibold uppercase tracking-wide text-slate-400">{text}</div>; }
function Stat({ label, value, big }) { return <div className="rounded-lg border border-slate-700 bg-slate-800/40 p-2 text-center"><div className="text-[10px] uppercase tracking-wide text-slate-500">{label}</div><div className={`font-mono font-semibold text-slate-100 ${big ? "text-base" : "text-sm"}`}>{value}</div></div>; }
function Row({ name, right, color }) { return <div className="flex items-center justify-between rounded-md border border-slate-800 bg-slate-800/40 px-2.5 py-1.5"><div className="flex items-center gap-2"><span className={`h-2 w-2 rounded-full ${DOT[color] || "bg-slate-500"}`} /><span className="text-xs text-slate-200">{name}</span></div><span className="font-mono text-[11px] text-slate-400">{right}</span></div>; }
function SectionLabel({ icon: Icon, text }) { return <div className="flex items-center gap-1.5 px-3 pb-2 pt-3 text-[11px] font-semibold uppercase tracking-wide text-slate-500"><Icon className="h-3.5 w-3.5" /> {text}</div>; }
function Mini({ label, value }) { return <div className="rounded border border-slate-700 bg-slate-800/50 px-1 py-1.5"><div className="text-[9px] uppercase tracking-wide text-slate-500">{label}</div><div className="font-mono text-[11px] text-slate-200">{value}</div></div>; }
